  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("RAMA", 16, "666666")], alignment: AlignmentType.CENTER })], 1, "FFFFFF"),
      createCell([new Paragraph({ children: [boldText(frameText1 + frameText2, 20)], alignment: AlignmentType.CENTER })], 3)
    ]
  }));

  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("MAX. OBCIĄŻENIE POLA", 18, "666666")] })], 2, "FFFFFF"),
      createCell([new Paragraph({ children: [boldText("Qp=", 20, "666666")], alignment: AlignmentType.CENTER })], 1),
      createCell([new Paragraph({ children: [boldText(totalBayLoad, 24), unitText("kg", 18)], alignment: AlignmentType.CENTER })], 1)
