const boldText = (text: string | number, size: number = 20, color: string = "000000") => new TextRun({ 
  text: String(text), 
  bold: true, 
  size: size, 
  font: "Arial", 
  color: color 
});
const normalText = (text: string | number, size: number = 20, color: string = "000000") => new TextRun({ text: String(text), size: size, font: "Arial", color: color });
const unitText = (text: string, size: number = 18) => new TextRun({ text: ` ${text}`, size: size, font: "Arial", color: "666666", bold: true });

const createCell = (content: Paragraph[], colSpan: number = 1, shading: string = "FFFFFF", borders = true) => {
  return new TableCell({
    children: content,
    columnSpan: colSpan,
    shading: { fill: shading },
    verticalAlign: VerticalAlign.CENTER,
    margins: { top: 60, bottom: 60, left: 100, right: 100 },
    borders: borders ? {
      top: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
      bottom: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
      left: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
      right: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
    } : undefined
  });
};

