        ]
      }));
    });
  } else {
    const count1 = data.subsequentLevels.length;
    const count2 = data.subsequentLevels2 ? data.subsequentLevels2.length : 0;
    const maxRows = Math.max(count1, count2);

    for (let i = 0; i < maxRows; i++) {
       const l1 = data.subsequentLevels[i];
       const l2 = data.subsequentLevels2 ? data.subsequentLevels2[i] : undefined;

       const cell1Nodes = l1 ? [normalText(`${getLevelLabel(l1, 'A')} = `, 16, "666666"), boldText(l1.height, 18), unitText("mm", 14)] : [];
       const cell2Nodes = l2 ? [normalText(`${getLevelLabel(l2, 'B')} = `, 16, "666666"), boldText(l2.height, 18), unitText("mm", 14)] : [];

       contentRows.push(new TableRow({
        children: [
          createCell([new Paragraph({ children: [boldText(i === 0 ? "KOLEJNE POZIOMY" : "", 16, "666666")] })], 2, "FFFFFF"),
          createCell([new Paragraph({ children: cell1Nodes, alignment: AlignmentType.CENTER })], 1),
          createCell([new Paragraph({ children: cell2Nodes, alignment: AlignmentType.CENTER })], 1)
        ]
      }));
    }
  }

  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("MAKSYMALNE OBCIĄŻENIE PARY TRAWERSÓW", 18)], alignment: AlignmentType.CENTER })], 4, "FFFFFF")
    ]
