  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("POZIOM", 14, "666666")], alignment: AlignmentType.CENTER })], 1, "FFFFFF"),
      createCell([new Paragraph({ children: [boldText("DŁ. (L)", 14, "666666")], alignment: AlignmentType.CENTER })], 1, "FFFFFF"),
      createCell([new Paragraph({ children: [boldText("PROFIL", 14, "666666")], alignment: AlignmentType.CENTER })], 1, "FFFFFF"),
