const boldText = (text: string | number, size: number = 20, color: string = "000000") => new TextRun({ 
  text: String(text), 
  bold: true, 
  size: size, 
  font: "Arial", 
  color: color 
});
const normalText = (text: string | number, size: number = 20, color: string = "000000") => new TextRun({ text: String(text), size: size, font: "Arial", color: color });
const unitText = (text: string, size: number = 18) => new TextRun({ text: ` ${text}`, size: size, font: "Arial", color: "666666", bold: true });

const createCell = (content: Paragraph[], colSpan: number = 1, shading: string = "FFFFFF", borders = true) => {
  return new TableCell({
    children: content,
    columnSpan: colSpan,
    shading: { fill: shading },
    verticalAlign: VerticalAlign.CENTER,
    margins: { top: 60, bottom: 60, left: 100, right: 100 },
    borders: borders ? {
      top: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
      bottom: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
      left: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
      right: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
    } : undefined
  });
};

const createPlateTable = (data: PlateData) => {
  const totalBayLoad = calculateMaxBayLoad(data);
  const formattedDate = formatMonthYear(data.nextInspectionDate);
  const rackHeight = calculateTotalHeight(data);
  // firstLevelHeight2 is now defined in PlateData interface
  const hasSecondConfig = (data.firstLevelHeight2 !== undefined && data.firstLevelHeight2 !== null) || (data.subsequentLevels2 && data.subsequentLevels2.length > 0);

  const rows: TableRow[] = [];

  // --- Header Row ---
  rows.push(new TableRow({
    children: [
      new TableCell({
        children: [
          new Paragraph({ children: [boldText("ROK INSTALACJI", 14, "666666")], alignment: AlignmentType.LEFT }),
          new Paragraph({ children: [boldText(data.installationYear, 32)], alignment: AlignmentType.LEFT }),
        ],
        width: { size: 40, type: WidthType.PERCENTAGE },
        borders: { bottom: { style: BorderStyle.SINGLE, size: 4 } }
      }),
      new TableCell({
        children: [
          new Paragraph({ 
            children: [
              ...(data.rackNumber ? [boldText(`NR: ${data.rackNumber}  `, 24)] : []),
              boldText(data.customerName.toUpperCase(), 24)
            ], 
            alignment: AlignmentType.RIGHT 
          }),
          new Paragraph({ 
            children: [
              normalText("PROJEKT: ", 16, "666666"),
              boldText(data.projectNumber, 16),
              normalText(`  SAP: 46120${data.sapNumberSuffix}`, 16, "666666")
            ], 
            alignment: AlignmentType.RIGHT 
          }),
        ],
        width: { size: 60, type: WidthType.PERCENTAGE },
        borders: { bottom: { style: BorderStyle.SINGLE, size: 4 } }
      })
    ]
  }));

  rows.push(new TableRow({ height: { value: 100, rule: HeightRule.EXACT }, children: [new TableCell({ children: [], columnSpan: 2, borders: { top: { style: BorderStyle.NIL }, bottom: { style: BorderStyle.NIL }, left: { style: BorderStyle.NIL }, right: { style: BorderStyle.NIL } } })] }));

  const contentRows: TableRow[] = [];

  if (!hasSecondConfig) {
     contentRows.push(new TableRow({
      children: [
        createCell([new Paragraph({ children: [boldText("MAX. WYSOKOŚĆ 1. POZIOMU", 18, "666666")] })], 2, "FFFFFF"),
        createCell([new Paragraph({ children: [boldText("A = ", 24), boldText(data.firstLevelHeight ?? 0, 24), unitText("mm", 18)], alignment: AlignmentType.CENTER })], 2)
      ]
    }));
  } else {
     contentRows.push(new TableRow({
      children: [
        createCell([new Paragraph({ children: [boldText("MAX. WYSOKOŚĆ 1. POZIOMU", 18, "666666")] })], 2, "FFFFFF"),
        createCell([new Paragraph({ children: [boldText(`A=${data.firstLevelHeight}`, 20), unitText("mm", 16)], alignment: AlignmentType.CENTER })], 1),
        // Resolving firstLevelHeight2 access errors
        createCell([new Paragraph({ children: [data.firstLevelHeight2 ? boldText(`A=${data.firstLevelHeight2}`, 20) : normalText(''), data.firstLevelHeight2 ? unitText("mm", 16) : normalText('')], alignment: AlignmentType.CENTER })], 1)
      ]
    }));
  }

  if (!hasSecondConfig) {
     data.subsequentLevels.forEach((lvl, idx) => {
      contentRows.push(new TableRow({
        children: [
          createCell([new Paragraph({ children: [boldText(idx === 0 ? "KOLEJNE POZIOMY" : "", 16, "666666")] })], 2, "FFFFFF"),
          createCell([new Paragraph({ children: [normalText(`${getLevelLabel(lvl, 'A')} = `, 18, "666666"), boldText(lvl.height, 22), unitText("mm", 18)], alignment: AlignmentType.CENTER })], 2)
        ]
      }));
    });
  } else {
    const count1 = data.subsequentLevels.length;
    const count2 = data.subsequentLevels2 ? data.subsequentLevels2.length : 0;
    const maxRows = Math.max(count1, count2);

    for (let i = 0; i < maxRows; i++) {
       const l1 = data.subsequentLevels[i];
       const l2 = data.subsequentLevels2 ? data.subsequentLevels2[i] : undefined;

       const cell1Nodes = l1 ? [normalText(`${getLevelLabel(l1, 'A')} = `, 16, "666666"), boldText(l1.height, 18), unitText("mm", 14)] : [];
       const cell2Nodes = l2 ? [normalText(`${getLevelLabel(l2, 'B')} = `, 16, "666666"), boldText(l2.height, 18), unitText("mm", 14)] : [];

       contentRows.push(new TableRow({
        children: [
          createCell([new Paragraph({ children: [boldText(i === 0 ? "KOLEJNE POZIOMY" : "", 16, "666666")] })], 2, "FFFFFF"),
          createCell([new Paragraph({ children: cell1Nodes, alignment: AlignmentType.CENTER })], 1),
          createCell([new Paragraph({ children: cell2Nodes, alignment: AlignmentType.CENTER })], 1)
        ]
      }));
    }
  }

  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("MAKSYMALNE OBCIĄŻENIE PARY TRAWERSÓW", 18)], alignment: AlignmentType.CENTER })], 4, "FFFFFF")
    ]
  }));

  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("POZIOM", 14, "666666")], alignment: AlignmentType.CENTER })], 1, "FFFFFF"),
      createCell([new Paragraph({ children: [boldText("DŁ. (L)", 14, "666666")], alignment: AlignmentType.CENTER })], 1, "FFFFFF"),
      createCell([new Paragraph({ children: [boldText("PROFIL", 14, "666666")], alignment: AlignmentType.CENTER })], 1, "FFFFFF"),
      createCell([new Paragraph({ children: [boldText("MAX. OBCIĄŻENIE", 14, "666666")], alignment: AlignmentType.CENTER })], 1, "FFFFFF"),
    ]
  }));

  data.beams.forEach(beam => {
    const qMax = calculateQmax(beam.loadCount, beam.loadWeight);
    contentRows.push(new TableRow({
      children: [
        createCell([new Paragraph({ children: [boldText(beam.levelLabel, 18)], alignment: AlignmentType.CENTER })]),
        createCell([new Paragraph({ children: [boldText(beam.length, 22), unitText("mm", 16)], alignment: AlignmentType.CENTER })]),
        createCell([new Paragraph({ children: [boldText(`AUF'B'${beam.profileType}`, 20), normalText(` (${beam.profileWidth}x50)`, 16, "666666")], alignment: AlignmentType.CENTER })]),
        createCell([new Paragraph({ children: [boldText(`Qmax= ${qMax}`, 22), unitText("kg", 18), new TextRun({ text: `\n(${beam.loadCount} x ${beam.loadWeight} kg)`, size: 14, color: "999999" })], alignment: AlignmentType.CENTER })]),
      ]
    }));
  });

  const frameText1 = `STD'B'${data.frameType}'${data.frameDepth}'${data.frameHeight}`;
  const frameText2 = data.frameType2 ? ` oraz STD'B'${data.frameType2}'${data.frameDepth2}'${data.frameHeight2}` : '';

  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("RAMA", 16, "666666")], alignment: AlignmentType.CENTER })], 1, "FFFFFF"),
      createCell([new Paragraph({ children: [boldText(frameText1 + frameText2, 20)], alignment: AlignmentType.CENTER })], 3)
    ]
  }));

  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("MAX. OBCIĄŻENIE POLA", 18, "666666")] })], 2, "FFFFFF"),
      createCell([new Paragraph({ children: [boldText("Qp=", 20, "666666")], alignment: AlignmentType.CENTER })], 1),
      createCell([new Paragraph({ children: [boldText(totalBayLoad, 24), unitText("kg", 18)], alignment: AlignmentType.CENTER })], 1)
    ]
  }));

  contentRows.push(new TableRow({
    children: [
      createCell([new Paragraph({ children: [boldText("WYSOKOŚĆ REGAŁU", 18, "666666")] })], 2, "FFFFFF"),
      createCell([new Paragraph({ children: [boldText("H=", 20, "999999")], alignment: AlignmentType.CENTER })], 1),
      createCell([new Paragraph({ children: [boldText(rackHeight, 24), unitText("mm", 18)], alignment: AlignmentType.CENTER })], 1)
    ]
  }));

  const dataTable = new Table({
    rows: contentRows,
    width: { size: 100, type: WidthType.PERCENTAGE },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 4 },
      bottom: { style: BorderStyle.SINGLE, size: 4 },
      left: { style: BorderStyle.SINGLE, size: 4 },
      right: { style: BorderStyle.SINGLE, size: 4 },
      insideHorizontal: { style: BorderStyle.SINGLE, size: 2 },
      insideVertical: { style: BorderStyle.SINGLE, size: 2 },
    }
  });

  rows.push(new TableRow({
    children: [
      new TableCell({
        children: [dataTable],
        columnSpan: 2,
        borders: { top: { style: BorderStyle.NIL }, bottom: { style: BorderStyle.NIL }, left: { style: BorderStyle.NIL }, right: { style: BorderStyle.NIL } }
      })
    ]
  }));

  rows.push(new TableRow({ height: { value: 100, rule: HeightRule.EXACT }, children: [new TableCell({ children: [], columnSpan: 2, borders: { top: { style: BorderStyle.NIL }, bottom: { style: BorderStyle.NIL }, left: { style: BorderStyle.NIL }, right: { style: BorderStyle.NIL } } })] }));

  rows.push(new TableRow({
    children: [
      new TableCell({
        children: [
          new Paragraph({ children: [boldText("ADRES DOSTAWCY:", 14, "666666")] }),
          new Paragraph({ children: [normalText("Jungheinrich Polska Sp. Z o.o.", 14)] }),
          new Paragraph({ children: [normalText("ul. Świerkowa 3 Bronisze k. Warszawy", 14)] }),
          new Paragraph({ children: [normalText("05-850 Ożarów Mazowiecki", 14)] }),
        ],
        width: { size: 40, type: WidthType.PERCENTAGE },
        borders: { top: { style: BorderStyle.SINGLE, size: 4 }, right: { style: BorderStyle.SINGLE, size: 2 } }
      }),
      new TableCell({
        children: [
          new Paragraph({ children: [boldText("NASTĘPNY PRZEGLĄD TECHNICZNY", 16, "999999")], alignment: AlignmentType.LEFT }),
          new Paragraph({ children: [boldText(formattedDate, 32)], alignment: AlignmentType.LEFT }),
        ],
        width: { size: 60, type: WidthType.PERCENTAGE },
        verticalAlign: VerticalAlign.CENTER,
        borders: { top: { style: BorderStyle.SINGLE, size: 4 } }
      })
    ]
  }));

  const plateContainer = new Table({
    rows: rows,
    width: { size: 100, type: WidthType.PERCENTAGE },
    borders: {
      top: { style: BorderStyle.NIL },
      bottom: { style: BorderStyle.NIL },
      left: { style: BorderStyle.NIL },
      right: { style: BorderStyle.NIL },
      insideHorizontal: { style: BorderStyle.NIL },
      insideVertical: { style: BorderStyle.NIL }
    }
  });

  return [
    new Paragraph({ children: [] }), 
    plateContainer,
    new Paragraph({ children: [], pageBreakBefore: true })
  ];
};

export const createDocxBlob = async (plates: PlateData[]): Promise<Blob> => {
  const allChildren: any[] = [];
  plates.forEach(plate => {
    const tableNodes = createPlateTable(plate);
    allChildren.push(...tableNodes);
  });
  const doc = new Document({
    sections: [{
      properties: {
        page: {
          margin: {
            top: 720,
            right: 720,
            bottom: 720,
            left: 720
          }
        }
      },
      children: allChildren
    }]
  });
  return await Packer.toBlob(doc);
};

