import { calculateQmax, calculateMaxBayLoad, formatMonthYear, calculateTotalHeight, getLevelLabel } from '../utils';

interface Props {
  data: PlateData;
}

const PalletPlatePreview: React.FC<Props> = ({ data }) => {
  const borderOuter = "border-2 border-black";
  const borderInner = "border-b border-black last:border-b-0";
  const borderRight = "border-r border-black";

  const totalBayLoad = calculateMaxBayLoad(data);
  const formattedDate = formatMonthYear(data.nextInspectionDate);
  const rackHeight = calculateTotalHeight(data);
  const hasSecondConfig = (data.firstLevelHeight2 !== undefined && data.firstLevelHeight2 !== null) || (data.subsequentLevels2 && data.subsequentLevels2.length > 0);

  const count1 = data.subsequentLevels.length;
  const count2 = data.subsequentLevels2 ? data.subsequentLevels2.length : 0;
  const maxRows = Math.max(count1, count2);
  const rows = Array.from({ length: maxRows }, (_, i) => i);

  const unitClass = "text-[10px] text-gray-400 font-semibold ml-0.5 leading-none";
  const labelClass = "text-gray-600 font-bold uppercase";
  const levelLabelClass = "text-base font-bold text-gray-700 mr-2";

  return (
    <div 
      className="bg-white text-black font-technical box-border overflow-hidden relative flex flex-col"
      style={{ 
        width: '190mm', 
        minHeight: '45mm',
        margin: '0 auto',
        padding: '0',
        pageBreakInside: 'avoid',
        printColorAdjust: 'exact'
      }}
    >
      <div className="flex justify-between items-end px-3 pt-1 pb-0.5 shrink-0 h-[11mm]">
        <div className="flex flex-col justify-center">
           <span className="text-[10px] uppercase text-gray-600 font-bold leading-none mb-0.5">Rok instalacji</span>
           <span className="text-2xl font-bold leading-none">{data.installationYear}</span>
        </div>
        <div className="text-right flex flex-col items-end justify-center">
           <div className="flex items-baseline gap-4">
              {data.rackNumber && <span className="text-xl font-bold">NR: {data.rackNumber}</span>}
              <span className="text-lg font-bold uppercase">{data.customerName}</span>
           </div>
           <div className="text-[10px] leading-tight mt-0.5 text-gray-600">
             PROJEKT: <b className="text-sm text-black">{data.projectNumber}</b> <span className="ml-2">SAP: <b className="text-sm text-black">46120{data.sapNumberSuffix}</b></span>
           </div>
        </div>
      </div>

      <div className={`w-full ${borderOuter} flex flex-col text-sm mx-0.5 mb-0.5 self-center max-w-[99%] bg-white`}>
        <div className={`flex ${borderInner} bg-white`}>
          <div className={`w-[70%] px-3 py-[1px] flex items-center ${borderRight}`}>
            <span className={`text-xs ${labelClass}`}>Max. wysokość 1. poziomu</span>
          </div>
          {!hasSecondConfig ? (
            <div className={`w-[30%] px-2 py-[1px] text-center flex items-baseline justify-center`}>
              <span className={levelLabelClass}>A =</span>
              <span className="text-xl font-bold">{data.firstLevelHeight}<span className={unitClass}>mm</span></span>
            </div>
          ) : (
            <>
              <div className={`w-[15%] px-1 py-[1px] text-center flex items-baseline justify-center border-r border-black`}>
                <span className="text-xs font-bold mr-1">A=</span>
                <span className="text-lg font-bold">{data.firstLevelHeight}<span className={unitClass}>mm</span></span>
              </div>
              <div className={`w-[15%] px-1 py-[1px] text-center flex items-baseline justify-center`}>
                 {data.firstLevelHeight2 && <><span className="text-xs font-bold mr-1">A=</span><span className="text-lg font-bold">{data.firstLevelHeight2}<span className={unitClass}>mm</span></span></>}
              </div>
            </>
          )}
        </div>

        <div className="flex-col">
          {!hasSecondConfig ? (
            data.subsequentLevels.map((level, idx) => (
              <div key={level.id} className={`flex border-b border-black`}>
                <div className={`w-[70%] px-3 py-[1px] flex items-center ${borderRight}`}>
                  <span className={`text-xs ${labelClass}`}>{idx === 0 ? "Kolejne poziomy" : "\u00A0"}</span>
                </div>
                <div className={`w-[30%] px-2 py-[1px] text-center flex items-baseline justify-center`}>
                  <span className={levelLabelClass}>{`${getLevelLabel(level, 'A')} =`}</span>
                  <span className="text-xl font-bold">{level.height}<span className={unitClass}>mm</span></span>
                </div>
              </div>
            ))
          ) : (
             rows.map((idx) => (
                <div key={idx} className={`flex border-b border-black`}>
                  <div className={`w-[70%] px-3 py-[1px] flex items-center ${borderRight}`}>
                    <span className={`text-xs ${labelClass}`}>{idx === 0 ? "Kolejne poziomy" : "\u00A0"}</span>
                  </div>
                  <div className={`w-[15%] px-1 py-[1px] text-center flex items-baseline justify-center border-r border-black`}>
                    {data.subsequentLevels[idx] && <><span className="text-xs font-bold mr-1">{`${getLevelLabel(data.subsequentLevels[idx], 'A')} =`}</span><span className="text-lg font-bold">{data.subsequentLevels[idx].height}<span className={unitClass}>mm</span></span></>}
                  </div>
                  <div className={`w-[15%] px-1 py-[1px] text-center flex items-baseline justify-center`}>
                     {data.subsequentLevels2[idx] && <><span className="text-xs font-bold mr-1">{`${getLevelLabel(data.subsequentLevels2[idx], 'B')} =`}</span><span className="text-lg font-bold">{data.subsequentLevels2[idx].height}<span className={unitClass}>mm</span></span></>}
                  </div>
                </div>
             ))
          )}
        </div>

        <div className={`${borderInner} bg-white text-black text-center py-[1px] text-[10px] uppercase font-extrabold border-b-2 leading-none`}>
          Maksymalne obciążenie pary trawersów
        </div>

        <div className="flex-col">
          {data.beams.map((beam) => {
            const qMax = calculateQmax(beam.loadCount, beam.loadWeight);
            return (
              <div key={beam.id} className={`flex ${borderInner}`}>
                <div className={`w-[15%] flex justify-center items-center px-1 text-base font-bold ${borderRight}`}>{beam.levelLabel}</div>
                <div className={`w-[15%] flex justify-center items-baseline px-1 text-xl font-bold ${borderRight}`}>{beam.length}<span className={unitClass}>mm</span></div>
                <div className={`w-[35%] text-center font-bold flex justify-center items-center gap-1 ${borderRight}`}>
                  <span className="text-lg leading-none">{`AUF'B'${beam.profileType}`}</span>
                  <span className="text-sm text-gray-400 leading-none">{`(${beam.profileWidth}x50)`}</span>
                </div>
                <div className={`w-[35%] flex flex-col justify-center items-center px-1`}>
                  <div className="flex items-baseline gap-3 leading-none">
                    <span className="text-[10px] mr-1 text-gray-400 font-bold">Qmax=</span>
                    <span className="text-lg font-bold">{qMax}<span className={unitClass}>kg</span></span>
                    <span className="text-[10px] text-gray-400 font-semibold">{`(${beam.loadCount}x${beam.loadWeight})`}</span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        <div className={`flex ${borderInner} border-t border-black shrink-0`}>
           <div className={`w-[30%] text-center text-[11px] font-bold uppercase py-1 ${borderRight} flex items-center justify-center`}><span className={labelClass}>Rama</span></div>
           <div className={`w-[70%] text-center text-lg font-bold py-1 px-2`}>{`STD'B'${data.frameType}'${data.frameDepth}'${data.frameHeight}`} {data.frameType2 && <span className="text-xs font-normal text-gray-400">oraz</span>} {data.frameType2 && `STD'B'${data.frameType2}'${data.frameDepth2}'${data.frameHeight2}`}</div>
        </div>

        <div className={`flex ${borderInner} shrink-0 bg-white`}>
           <div className={`w-[60%] px-3 text-[10px] font-bold uppercase py-1 ${borderRight} flex items-center leading-none`}><span className={labelClass}>max. obciążenie pola</span></div>
           <div className={`w-[10%] text-center text-xs font-bold py-1 ${borderRight} flex items-center justify-center text-gray-600`}>Qp=</div>
           <div className={`w-[30%] text-center text-xl font-bold py-1 flex items-baseline justify-center`}>{totalBayLoad}<span className={unitClass}>kg</span></div>
        </div>

        <div className={`flex shrink-0 bg-white`}>
           <div className={`w-[60%] px-3 text-[10px] font-bold uppercase py-1 ${borderRight} flex items-center leading-none`}><span className={labelClass}>Wysokość regału</span></div>
           <div className={`w-[10%] text-center text-xs font-bold py-1 ${borderRight} flex items-center justify-center text-gray-600`}>H=</div>
           <div className={`w-[30%] text-center text-xl font-bold py-1 flex items-baseline justify-center`}>{rackHeight}<span className={unitClass}>mm</span></div>
        </div>
      </div>

      <div className={`w-[99%] mx-auto flex border-t-2 border-black h-[14mm] mt-auto bg-white`}>
        <div className={`w-[45%] pr-2 py-0.5 text-[9px] flex flex-col justify-center border-r border-black/10 pl-2`}>
          <div className="font-bold text-gray-600 uppercase mb-0.5">Adres Dostawcy:</div>
          <div>Jungheinrich Polska Sp. Z o.o.</div>
          <div>ul. Świerkowa 3 Bronisze k. Warszawy, 05-850 Ożarów Maz.</div>
        </div>
        <div className={`w-[55%] pl-3 py-0.5 flex flex-col justify-center`}>
          <div className="text-[10px] font-bold uppercase text-gray-400">Następny przegląd techniczny</div>
          <div className="text-2xl font-bold">{formattedDate}</div>
        </div>
      </div>
    </div>
  );
};

