import React, { useState, useEffect, useRef, useCallback } from 'react';
import { PlateEditor } from './components/PlateEditor';
import { PlatePreview } from './components/PlatePreview';
import { GlobalEditorModal } from './components/GlobalEditorModal';
import { PlateData, INITIAL_PLATE } from './types';
import { Printer, Plus, FileText, Layout, Layers, Sheet, Download, Upload, FileDown, Settings2, Undo2, Menu, Eye, Edit3, GripVertical, ListOrdered } from 'lucide-react';
import { createDocxBlob } from './utils';

const STORAGE_KEY = 'plateGeneratorData';
const LABELS_PER_PAGE_KEY = 'labelsPerPage';
const MAX_UNDO_STEPS = 50;

const App: React.FC = () => {
  const [plates, setPlates] = useState<PlateData[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? JSON.parse(saved) : [{ ...INITIAL_PLATE }];
    } catch (e) {
      console.error("Failed to load persistence", e);
      return [{ ...INITIAL_PLATE }];
    }
  });

  const [labelsPerPage, setLabelsPerPage] = useState<number>(() => {
    const saved = localStorage.getItem(LABELS_PER_PAGE_KEY);
    return saved ? parseInt(saved) : 3;
  });

  const [activePlateId, setActivePlateId] = useState<string>(plates[0].id);
  const [viewMode, setViewMode] = useState<'single' | 'sheet'>('single');
  const [mobileTab, setMobileTab] = useState<'editor' | 'preview'>('preview'); 
  const [isGlobalEditorOpen, setIsGlobalEditorOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [leftPanelWidth, setLeftPanelWidth] = useState(60); 
  const [isResizing, setIsResizing] = useState(false);
  const [previewScale, setPreviewScale] = useState(1);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewContainerRef = useRef<HTMLDivElement>(null);

  const [undoStack, setUndoStack] = useState<PlateData[][]>([]);
  const lastSavedStateRef = useRef<PlateData[]>(plates);
  const saveTimeoutRef = useRef<number | null>(null);

  const startResizing = useCallback((e: React.MouseEvent) => {
    setIsResizing(true);
    e.preventDefault();
  }, []);

  const stopResizing = useCallback(() => {
    setIsResizing(false);
  }, []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing) {
      const newWidth = (e.clientX / window.innerWidth) * 100;
      if (newWidth > 20 && newWidth < 80) setLeftPanelWidth(newWidth);
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  useEffect(() => {
    const updateScale = () => {
      if (previewContainerRef.current) {
        const containerWidth = previewContainerRef.current.offsetWidth - 40; 
        const plateWidthPx = 190 * 3.78; 
        const newScale = Math.min(containerWidth / plateWidthPx, 1.2);
        setPreviewScale(newScale);
      }
    };
    const observer = new ResizeObserver(updateScale);
    if (previewContainerRef.current) observer.observe(previewContainerRef.current);
    updateScale();
    return () => observer.disconnect();
  }, [leftPanelWidth, viewMode]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(plates));
  }, [plates]);

  const updatePlatesWithHistory = (newPlates: PlateData[], immediate = false) => {
    const currentState = lastSavedStateRef.current;
    const saveToStack = () => {
      setUndoStack(prev => {
        const next = [...prev, currentState];
        if (next.length > MAX_UNDO_STEPS) return next.slice(1);
        return next;
      });
      lastSavedStateRef.current = newPlates;
    };
    if (immediate) {
      if (saveTimeoutRef.current) window.clearTimeout(saveTimeoutRef.current);
      saveToStack();
    } else {
      if (saveTimeoutRef.current) window.clearTimeout(saveTimeoutRef.current);
      saveTimeoutRef.current = window.setTimeout(saveToStack, 500);
    }
    setPlates(newPlates);
  };

  const activePlate = plates.find(p => p.id === activePlateId) || plates[0];

  const updateActivePlate = (newData: PlateData) => {
    const newPlates = plates.map(p => p.id === newData.id ? newData : p);
    updatePlatesWithHistory(newPlates);
  };

  const addNewPlateConfig = () => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newPlate: PlateData = { ...INITIAL_PLATE, id: newId, quantity: 1 };
    updatePlatesWithHistory([...plates, newPlate], true);
    setActivePlateId(newId);
  };

  // Grouping print queue by type to avoid mixed layouts on one page
  const printQueue: PlateData[] = plates.flatMap(p => Array(p.quantity).fill(p));

  const pages: PlateData[][] = [];
  let currentLabels: PlateData[] = [];
  let currentType: string | null = null;

  printQueue.forEach(plate => {
    const maxOnPage = plate.type === 'shelf' ? 9 : labelsPerPage;

    if (currentType !== plate.type || currentLabels.length >= maxOnPage) {
      if (currentLabels.length > 0) pages.push(currentLabels);
      currentLabels = [plate];
      currentType = plate.type;
    } else {
      currentLabels.push(plate);
    }
  });
  if (currentLabels.length > 0) pages.push(currentLabels);

  return (
    <div className={`h-screen flex flex-col overflow-hidden bg-gray-50 ${isResizing ? 'cursor-col-resize select-none' : ''}`}>
      <header className="bg-slate-900 text-white p-2 md:p-3 shadow-lg no-print z-30 shrink-0">
        <div className="w-full px-2 md:px-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-800 rounded-lg lg:2xl:hidden block"><Menu size={20} /></button>
            <h1 className="text-lg md:text-xl font-bold truncate">Generator Tabliczek</h1>
          </div>
          <div className="flex items-center gap-2">
             <button onClick={() => setUndoStack([])} className="p-2 text-gray-500 hover:text-white"><Undo2 size={18} /></button>
             <button onClick={() => window.print()} className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2 shadow-lg">
              <Printer size={18} /> <span>Drukuj</span> <span className="text-xs opacity-70">({printQueue.length})</span>
             </button>
          </div>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden w-full relative">
        <aside className={`${isSidebarOpen ? 'translate-x-0' : '-translate-x-full 2xl:translate-x-0'} fixed 2xl:static top-0 left-0 h-full z-40 w-72 bg-white border-r overflow-y-auto no-print transition-transform duration-300`}>
          <div className="p-4 border-b bg-gray-50 flex justify-between items-center sticky top-0 z-10">
             <span className="font-bold text-gray-700 text-xs">PROJEKTY</span>
             <button onClick={addNewPlateConfig} className="bg-green-600 text-white p-1.5 rounded hover:bg-green-700 shadow-sm"><Plus size={16} /></button>
          </div>
          <div className="p-2 space-y-2">
            {plates.map((plate, idx) => (
              <div key={plate.id} onClick={() => setActivePlateId(plate.id)} className={`p-3 rounded-xl cursor-pointer border transition-all ${activePlateId === plate.id ? 'border-blue-500 bg-blue-50 shadow-md ring-2 ring-blue-100' : 'border-gray-200'}`}>
                <div className="flex justify-between items-start mb-1">
                  <span className="font-bold text-gray-800 text-xs uppercase">{plate.type === 'pallet' ? 'Paletowy' : 'Półkowy'}</span>
                  <span className="bg-white border text-blue-600 text-[9px] px-1.5 py-0.5 rounded-full font-bold">{plate.quantity} szt.</span>
                </div>
                <div className="text-[10px] text-gray-500 truncate">{plate.customerName}</div>
              </div>
            ))}
          </div>
        </aside>

        <div className="flex-1 flex overflow-hidden no-print">
          <section ref={previewContainerRef} className={`${mobileTab === 'preview' ? 'flex' : 'hidden lg:flex'} bg-gray-200/50 flex flex-col border-r overflow-hidden`} style={{ width: window.innerWidth >= 1024 ? `${leftPanelWidth}%` : '100%' }}>
            <div className="p-3 bg-white border-b shadow-sm shrink-0 flex justify-between items-center">
              <span className="text-xs font-bold uppercase tracking-widest text-gray-400">Podgląd arkusza A4</span>
              <div className="flex bg-gray-100 rounded-lg p-1 gap-1">
                 <button onClick={() => setViewMode('single')} className={`px-3 py-1 text-[10px] font-bold rounded ${viewMode === 'single' ? 'bg-white shadow' : 'text-gray-400'}`}>POJEDYNCZA</button>
                 <button onClick={() => setViewMode('sheet')} className={`px-3 py-1 text-[10px] font-bold rounded ${viewMode === 'sheet' ? 'bg-white shadow' : 'text-gray-400'}`}>ARKUSZ A4</button>
              </div>
            </div>
            <div className="flex-1 overflow-auto p-8 flex justify-center bg-slate-300/20">
              <div className="origin-top" style={{ transform: `scale(${previewScale * (viewMode === 'single' ? 1 : 0.65)})` }}>
                 {viewMode === 'single' ? (
                   <div className="bg-white shadow-2xl p-4"><PlatePreview data={activePlate} /></div>
                 ) : (
                   pages.map((pagePlates, pIdx) => (
                      <div key={pIdx} className="bg-white shadow-2xl mb-8 flex flex-col items-center" style={{ width: '210mm', minHeight: '297mm', padding: '10mm' }}>
                         <div className={`w-full ${pagePlates[0]?.type === 'shelf' ? 'grid grid-cols-3 gap-y-4 gap-x-4' : 'flex flex-col gap-12'}`}>
                            {pagePlates.map((p, i) => <div key={i} className="flex justify-center"><PlatePreview data={p} /></div>)}
                         </div>
                      </div>
                   ))
                 )}
              </div>
            </div>
          </section>

          <section className={`${mobileTab === 'editor' ? 'flex' : 'hidden lg:flex'} flex-1 bg-gray-100 p-8 overflow-y-auto`}>
            <div className="max-w-2xl mx-auto w-full">
              {activePlate && <PlateEditor data={activePlate} onChange={updateActivePlate} onDuplicate={() => addNewPlateConfig()} onRemove={() => {}} />}
            </div>
          </section>
        </div>

        {/* PRINT VIEW */}
        <div className="hidden print:block w-full bg-white">
           {pages.map((pagePlates, pIdx) => (
             <div key={pIdx} className={`w-full bg-white ${pIdx < pages.length - 1 ? 'page-break' : ''}`} style={{ width: '210mm', height: '297mm', padding: '10mm 15mm' }}>
                <div className={`w-full ${pagePlates[0]?.type === 'shelf' ? 'grid grid-cols-3 gap-y-8 gap-x-8' : 'flex flex-col gap-12'}`}>
                   {pagePlates.map((p, i) => <div key={i} className="flex justify-center"><PlatePreview data={p} /></div>)}
                </div>
             </div>
           ))}
        </div>
      </main>
    </div>
  );
};

export default App;
